"""Parser for mass-action reaction strings.

Grammar (one reaction per string)::

    <lhs> "->" <rhs> "@" <rate>

where each side is a ``+``-separated list of terms and each term is either
``Species`` or ``n Species`` (also accepts ``n*Species``).  The rate is a
positive float.  Examples::

    A + B -> C @ 0.01
    C -> A + B @ 0.1
    2 H2O -> H2O2 @ 3.5e-4

The parser produces a :class:`Network` holding

* the ordered species list,
* the net stoichiometry matrix ``S`` (n_species x n_reactions),
* the *reactant* stoichiometry matrix ``R`` (n_species x n_reactions), used
  to evaluate mass-action propensities ``v_i = k_i * prod_j x_j**R[i, j]``,
* the rate-constant vector ``k``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

import numpy as np

_TERM_RE = re.compile(r"^(?:(?P<coeff>\d+(?:\.\d+)?)\s*\*?\s*)?(?P<spec>[A-Za-z_]\w*)$")
_REACTION_RE = re.compile(
    r"^\s*(?P<lhs>[^@]+?)\s*->\s*(?P<rhs>[^@]+?)\s*@\s*(?P<rate>[+]?[\d.]+(?:[eE][+-]?\d+)?)\s*$"
)


class ParseError(ValueError):
    """Raised when a reaction string cannot be parsed."""


def _parse_side(side: str) -> dict[str, int]:
    """Parse one side of a reaction into a {species: coefficient} dict."""
    counts: dict[str, int] = {}
    for raw_term in side.split("+"):
        term = raw_term.strip()
        if not term:
            raise ParseError(f"empty term in reaction side: {side!r}")
        m = _TERM_RE.match(term)
        if not m:
            raise ParseError(f"cannot parse term {term!r} in side {side!r}")
        coeff = int(m.group("coeff")) if m.group("coeff") else 1
        spec = m.group("spec")
        if coeff <= 0:
            raise ParseError(f"coefficient must be positive, got {coeff} for {spec!r}")
        counts[spec] = counts.get(spec, 0) + coeff
    return counts


@dataclass
class Reaction:
    """One parsed reaction."""

    reactants: dict[str, int]
    products: dict[str, int]
    rate: float

    def __str__(self) -> str:
        def fmt(d: dict[str, int]) -> str:
            return " + ".join(
                f"{c} {s}" if c > 1 else s for s, c in sorted(d.items())
            )

        return f"{fmt(self.reactants)} -> {fmt(self.products)} @ {self.rate}"


def parse_reaction(string: str) -> Reaction:
    """Parse a single reaction string."""
    m = _REACTION_RE.match(string)
    if not m:
        raise ParseError(
            f"cannot parse reaction {string!r}; expected '<lhs> -> <rhs> @ <rate>'"
        )
    return Reaction(
        reactants=_parse_side(m.group("lhs")),
        products=_parse_side(m.group("rhs")),
        rate=float(m.group("rate")),
    )


@dataclass
class Network:
    """A reaction network with its stoichiometry matrices."""

    species: list[str]
    reactions: list[Reaction]
    S: np.ndarray  # net stoichiometry   (n_species x n_reactions)
    R: np.ndarray  # reactant stoich.   (n_species x n_reactions)
    rates: np.ndarray  # (n_reactions,)

    @property
    def n_species(self) -> int:
        return len(self.species)

    @property
    def n_reactions(self) -> int:
        return len(self.reactions)


def parse_network(strings) -> Network:
    """Parse an iterable of reaction strings into a :class:`Network`.

    Species are ordered by first appearance across all reactions.
    """
    reactions = [parse_reaction(s) for s in strings]
    species: list[str] = []
    seen: set[str] = set()

    def note(spec: str) -> None:
        if spec not in seen:
            seen.add(spec)
            species.append(spec)

    for rxn in reactions:
        for spec in rxn.reactants:
            note(spec)
        for spec in rxn.products:
            note(spec)

    n_sp, n_rx = len(species), len(reactions)
    idx = {s: i for i, s in enumerate(species)}
    S = np.zeros((n_sp, n_rx))
    R = np.zeros((n_sp, n_rx))
    for j, rxn in enumerate(reactions):
        for spec, c in rxn.products.items():
            S[idx[spec], j] += c
        for spec, c in rxn.reactants.items():
            S[idx[spec], j] -= c
            R[idx[spec], j] += c

    return Network(
        species=species,
        reactions=reactions,
        S=S,
        R=R,
        rates=np.array([rxn.rate for rxn in reactions], dtype=float),
    )

