from .cli import main

if __name__ == "__main__":
    raise SystemExit(main())

"""Parser tests."""

import numpy as np
import pytest

from rxnsim.parser import parse_network, parse_reaction, ParseError


def test_single_reaction():
    rxn = parse_reaction("A + B -> C @ 0.01")
    assert rxn.reactants == {"A": 1, "B": 1}
    assert rxn.products == {"C": 1}
    assert rxn.rate == 0.01


def test_coefficients_and_scientific_notation():
    rxn = parse_reaction("2 H2O -> H2O2 @ 3.5e-4")
    assert rxn.reactants == {"H2O": 2}
    assert rxn.products == {"H2O2": 1}
    assert rxn.rate == pytest.approx(3.5e-4)


def test_network_matrices():
    net = parse_network(["A + B -> C @ 0.01", "C -> A + B @ 0.1"])
    assert net.species == ["A", "B", "C"]
    # columns: reaction 1 then reaction 2
    np.testing.assert_allclose(
        net.S, [[-1, 1], [-1, 1], [1, -1]]
    )
    np.testing.assert_allclose(
        net.R, [[1, 0], [1, 0], [0, 1]]
    )
    np.testing.assert_allclose(net.rates, [0.01, 0.1])


def test_bad_string_raises():
    with pytest.raises(ParseError):
        parse_reaction("A + B -> C")
    with pytest.raises(ParseError):
        parse_reaction("A + -> B @ 1")


def test_str_roundtrip():
    assert str(parse_reaction("B + A -> 2 C @ 1")) == "A + B -> 2 C @ 1.0"

